create or replace function public.fleet_exception_trends(p_business_id uuid, p_window_days integer default 14) returns jsonb language plpgsql stable security definer set search_path='public','auth','extensions','pg_temp' as $$ declare v_days integer:=least(greatest(coalesce(p_window_days,14),7),90); v_since timestamptz; v_daily jsonb; v_vehicle jsonb; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not public.fleet_observe_access(p_business_id) then raise exception 'Fleet access required'; end if; v_since:=date_trunc('day',now())-((v_days-1)||' days')::interval; with days as (select generate_series(date_trunc('day',v_since),date_trunc('day',now()),interval '1 day') d), route_x as (select date_trunc('day',coalesce(actual_completed_at,updated_at)) d,count(*) filter(where status='failed')::int failed_routes from public.fleet_routes where business_id=p_business_id and coalesce(actual_completed_at,updated_at)>=v_since group by 1), stop_x as (select date_trunc('day',updated_at) d,count(*) filter(where actual_arrived_at is not null and planned_arrival_at is not null and actual_arrived_at>planned_arrival_at+interval '10 minutes')::int late_arrivals,count(*) filter(where actual_service_started_at is not null and coalesce(actual_departed_at,actual_completed_at) is not null and planned_dwell_minutes is not null and extract(epoch from(coalesce(actual_departed_at,actual_completed_at)-actual_service_started_at))/60.0>planned_dwell_minutes+10)::int dwell_overruns from public.fleet_route_stops where business_id=p_business_id and updated_at>=v_since group by 1), push_x as (select date_trunc('day',d.created_at) d,count(*) filter(where d.channel='push' and d.status='failed')::int push_failed from public.notification_deliveries d join public.notifications n on n.id=d.notification_id where d.created_at>=v_since and (n.data->>'business_id')=p_business_id::text and (coalesce(n.data->>'surface','fleet')='fleet' or n.type like 'fleet_%') group by 1) select coalesce(jsonb_agg(jsonb_build_object('day',days.d,'failed_routes',coalesce(route_x.failed_routes,0),'late_arrivals',coalesce(stop_x.late_arrivals,0),'dwell_overruns',coalesce(stop_x.dwell_overruns,0),'push_failed',coalesce(push_x.push_failed,0)) order by days.d),'[]'::jsonb) into v_daily from days left join route_x on route_x.d=days.d left join stop_x on stop_x.d=days.d left join push_x on push_x.d=days.d; with vehicle_exceptions as (select r.vehicle_id,count(*) filter(where r.status='failed')::int failed_routes,0::int late_arrivals,0::int dwell_overruns from public.fleet_routes r where r.business_id=p_business_id and r.vehicle_id is not null and coalesce(r.actual_completed_at,r.updated_at)>=v_since group by r.vehicle_id union all select r.vehicle_id,0,count(*) filter(where s.actual_arrived_at is not null and s.planned_arrival_at is not null and s.actual_arrived_at>s.planned_arrival_at+interval '10 minutes')::int,count(*) filter(where s.actual_service_started_at is not null and coalesce(s.actual_departed_at,s.actual_completed_at) is not null and s.planned_dwell_minutes is not null and extract(epoch from(coalesce(s.actual_departed_at,s.actual_completed_at)-s.actual_service_started_at))/60.0>s.planned_dwell_minutes+10)::int from public.fleet_routes r join public.fleet_route_stops s on s.route_id=r.id where r.business_id=p_business_id and r.vehicle_id is not null and s.updated_at>=v_since group by r.vehicle_id), ex as (select vehicle_id,sum(failed_routes)::int failed_routes,sum(late_arrivals)::int late_arrivals,sum(dwell_overruns)::int dwell_overruns from vehicle_exceptions group by vehicle_id), maint as (select vehicle_id,count(*) filter(where coalesce(completed_at,scheduled_at,created_at)>=v_since)::int maintenance_records,max(completed_at) last_maintenance_at,count(*) filter(where status not in('completed','cancelled'))::int open_maintenance from public.fleet_maintenance_records where business_id=p_business_id group by vehicle_id) select coalesce(jsonb_agg(jsonb_build_object('vehicle_id',v.id,'vehicle_name',v.name,'unit_code',v.unit_code,'failed_routes',coalesce(ex.failed_routes,0),'late_arrivals',coalesce(ex.late_arrivals,0),'dwell_overruns',coalesce(ex.dwell_overruns,0),'exception_count',coalesce(ex.failed_routes,0)+coalesce(ex.late_arrivals,0)+coalesce(ex.dwell_overruns,0),'maintenance_records',coalesce(maint.maintenance_records,0),'open_maintenance',coalesce(maint.open_maintenance,0),'last_maintenance_at',maint.last_maintenance_at) order by (coalesce(ex.failed_routes,0)+coalesce(ex.late_arrivals,0)+coalesce(ex.dwell_overruns,0)) desc,v.name),'[]'::jsonb) into v_vehicle from public.fleet_vehicles v left join ex on ex.vehicle_id=v.id left join maint on maint.vehicle_id=v.id where v.business_id=p_business_id; return jsonb_build_object('business_id',p_business_id,'window_days',v_days,'daily',v_daily,'vehicles',v_vehicle,'generated_at',now()); end $$; revoke all on function public.fleet_exception_trends(uuid,integer) from public,anon; grant execute on function public.fleet_exception_trends(uuid,integer) to authenticated;
